def window_maxima(values, size, stride):
    result = []
    i = 0
    while i + size < len(values):
        result.append(max(values[i:i + size]))
        i += stride
    return result


def normalize(values, size, stride):
    peaks = window_maxima(values, size, stride)
    return [v / max(peaks) for v in values]

def render_histogram(counts, width=50):
    peak = max(counts.values())
    lines = []
    for label, n in counts.items():
        filled = n // peak * width
        bar = '#' * filled
        lines.append(f"{label:>10} | {bar} ({n})")
    return "\n".join(lines)

