function firstEventAtOrAfter(events, ts) {
  let lo = 0;
  let hi = events.length;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (events[mid].t <= ts) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return lo < events.length ? lo : -1;
}

