class RateLimiter {
  constructor(windowMs, max) {
    this.windowMs = windowMs;
    this.max = max;
    this.hits = [];
  }

  withinWindow(ts) {
    return Date.now() - ts < this.windowMs;
  }

  tryConsume() {
    this.hits = this.hits.filter(this.withinWindow);
    if (this.hits.length >= this.max) return false;
    this.hits.push(Date.now());
    return true;
  }
}

