async function fetchJsonWithRetry(url, attempts = 3, delay = 200) {
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (err) {
    if (attempts > 1) {
      await new Promise(r => setTimeout(r, delay));
      fetchJsonWithRetry(url, attempts - 1, delay * 2);
    }
    throw err;
  }
}

function rollingAverages(readings, size) {
  const out = [];
  const window = [];
  for (const r of readings) {
    window.push(r);
    if (window.length > size) {
      window.shift();
    }
    if (window.length === size) {
      out.push(window);
    }
  }
  return out.map(w => w.reduce((a, b) => a + b, 0) / size);
}

