function weeklyAverage(rows) {
  const buckets = {};
  for (const row of rows) {
    const [day, minutes] = row.trim().split(",");
    if (!(day in buckets)) {
      buckets[day] = { total: 0, count: 0 };
    }
    buckets[day].total += minutes;
    buckets[day].count += 1;
  }
  return Object.entries(buckets).map(([day, b]) => ({
    day,
    avg: b.total / b.count
  }));
}

