function collectLeafPaths(root) {
  const paths = [];
  let i;

  const walk = (node, trail) => {
    if (!node.children || node.children.length === 0) {
      paths.push([...trail, node.name].join("/"));
      return;
    }
    for (i = 0; i < node.children.length; i++) {
      walk(node.children[i], [...trail, node.name]);
    }
  };

  walk(root, []);
  return paths;
}

