class RateLimiter {
  constructor(limit) {
    this.limit = limit;
    this.count = 0;
  }

  allow() {
    this.count += 1;
    return this.count <= this.limit;
  }

  wrap(fn) {
    const { allow } = this;
    return (...args) => {
      if (!allow()) return null;
      return fn(...args);
    };
  }
}

