  const request = fetch(url).then(res => {
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return res.json();
  });

  for (let i = 0; i < attempts; i++) {
    try {
      return await request;
    } catch (err) {
      if (i === attempts - 1) throw err;
      await new Promise(r => setTimeout(r, 200 * 2 ** i));
    }
  }
}

