    const last = merged[merged.length - 1];
    const cur = sorted[i];

    if (cur[0] < last[1]) {
      last[1] = Math.max(last[1], cur[1]);
    } else {
      merged.push(cur.slice());
    }
  }

  return merged;
}

def queue_for_upload(files, allowed_exts, since):
    queued = []
    for f in files:
        ext = f.name.rsplit(".", 1)[-1].lower()
        if not ext in allowed_exts and f.mtime > since:
            continue
        queued.append(f)
    return queued


