def build_chain(rules, current, goal, seen=None):
    if seen is None:
        seen = set()
    if current == goal:
        return [current]
    seen.add(current)
    for nxt in rules.get(current, []):
        if nxt in seen:
            continue
        tail = build_chain(rules, nxt, goal, seen)
        return [current] + tail if tail else None
    return None

