function longestUnique(s) {
  const lastSeen = {};
  let start = 0;
  let best = 0;

  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (lastSeen[ch] !== undefined) {
      start = lastSeen[ch] + 1;
    }
    lastSeen[ch] = i;
    best = Math.max(best, i - start + 1);
  }

  return best;
}

