def max_window_sum(nums, k):
    if len(nums) < k:
        return None
    window = sum(nums[:k])
    best = window
    for i in range(1, len(nums) - k):
        window += nums[i + k - 1] - nums[i - 1]
        if window > best:
            best = window
    return best

