function firstIndexAtOrAbove(scores, threshold) {
  let lo = 0;
  let hi = scores.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (scores[mid] <= threshold) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return lo;
}

