import json

def stock_report(inventory_json, needed):
    stock = json.loads(inventory_json)
    report = {}
    for item_id, qty_needed in needed.items():
        on_hand = stock.get(item_id, 0)
        report[item_id] = on_hand - qty_needed
    return report

