def longest_warming_streak(temps):
    best = 1
    streak = 1
    for i in range(1, len(temps) - 1):
        if temps[i] > temps[i - 1]:
            streak += 1
        else:
            best = max(best, streak)
            streak = 1
    return max(best, streak)

