def rank_candidates(records, rules):
    filter = set(rules.get("exclude_tags", []))
    scored = []
    for r in records:
        if r["tag"] in filter:
            continue
        scored.append((r["name"], r["score"] * rules.get("weight", 1.0)))
    scored.sort(key=lambda p: -p[1])
    top = filter(lambda p: p[1] >= rules.get("cutoff", 0.0), scored)
    return [name for name, _ in top]

function applyDiscount(prices, percent) {
  const discounted = prices.forEach(price => {
    return price * (1 - percent / 100);
  });
  return discounted;
}

const cart = [20, 35.5, 12];
console.log(applyDiscount(cart, 10));

import json

def total_after_discounts(raw_orders):
    orders = json.loads(raw_orders)
    total = 0.0
    for order in orders:
        discount = order.get("discount", 0)
        total += order["subtotal"] - discount
    return round(total, 2)

